// One atomic record per project; list metadata never carries original images.
async function wfStore(readKey,writes=[]){const db=await draftDB();try{return await new Promise((resolve,reject)=>{const tx=db.transaction('drafts',writes.length?'readwrite':'readonly'),store=tx.objectStore('drafts');let result;if(readKey){const req=store.get(readKey);req.onsuccess=()=>result=req.result}for(const [key,value] of writes)value===undefined?store.delete(key):store.put(value,key);tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('儲存已中止'))})}finally{db.close()}}
function wfQueue(task){const next=workflow.queue.then(task,task);workflow.queue=next.catch(()=>{});return next}
function wfThumb(){const c=pageCanvas(currentPage()),out=document.createElement('canvas'),s=Math.min(260/c.width,160/c.height,1);out.width=Math.max(1,Math.round(c.width*s));out.height=Math.max(1,Math.round(c.height*s));out.getContext('2d').drawImage(c,0,0,out.width,out.height);return out.toDataURL('image/png')}
function saveLibrary(){clearTimeout(workflow.timer);if(!image)return Promise.resolve(true);if(!workflow.projectId)workflow.projectId=uid();if(!workflow.projectName)workflow.projectName=plus.publication.title||currentPage()?.title||'未命名教材';const id=workflow.projectId,name=workflow.projectName,data=projectData(),thumb=wfThumb();return wfQueue(async()=>{const index=await wfStore('library-index')||[],entry={id,name,at:Date.now(),pages:data.pages.length,thumb};const next=[entry,...index.filter(p=>p.id!==id)];await wfStore(null,[['library:'+id,data],['library-index',next]]);workflow.library=next;$('libraryStatus').textContent='已保存「'+name+'」';return true}).catch(e=>{$('libraryStatus').textContent='教材未保存：'+e.message;toast('教材未保存，請下載專案備份');return false})}
scheduleDraft=function(){wfBase.scheduleDraft();clearTimeout(workflow.timer);if(image&&!studio.restoring)workflow.timer=setTimeout(()=>saveLibrary(),1400)};
async function libraryAction(action){try{await action()}catch(e){$('libraryStatus').textContent=e.message}}
async function refreshLibrary(){await workflow.queue;workflow.library=await wfStore('library-index')||[];renderLibrary()}
function renderLibrary(){const root=$('libraryGrid'),q=$('librarySearch').value.trim().toLowerCase();root.replaceChildren();for(const entry of workflow.library.filter(p=>p.name.toLowerCase().includes(q))){const card=wfElement('article'),img=wfElement('img'),name=wfElement('input'),meta=wfElement('small'),actions=wfElement('div');card.className='library-card';img.src=entry.thumb;img.alt=entry.name;name.value=entry.name;name.maxLength=120;name.setAttribute('aria-label','教材名稱');meta.textContent=entry.pages+' 頁 · '+new Date(entry.at).toLocaleString('zh-TW');name.onchange=()=>{if(workflow.projectId===entry.id)workflow.projectName=name.value.trim()||'未命名教材';libraryAction(()=>wfQueue(async()=>{const index=await wfStore('library-index')||[],record=index.find(x=>x.id===entry.id);if(!record)return;record.name=name.value.trim()||'未命名教材';await wfStore(null,[['library-index',index]]);if(workflow.projectId===entry.id)workflow.projectName=record.name;workflow.library=index;renderLibrary()}))};actions.append(wfButton('開啟',()=>libraryAction(async()=>{if(!await saveLibrary())return;await workflow.queue;const data=await wfStore('library:'+entry.id);if(!data)throw Error('找不到教材');const doc=await decodeProject(data);workflow.internalInstall=true;try{installDocument(doc)}finally{workflow.internalInstall=false}workflow.projectId=entry.id;workflow.projectName=entry.name;scheduleDraft();$('libraryDialog').close()})),wfButton('複製',()=>libraryAction(async()=>{if(workflow.projectId===entry.id&&!await saveLibrary())return;await wfQueue(async()=>{const data=await wfStore('library:'+entry.id);if(!data)throw Error('找不到教材');const id=uid(),index=await wfStore('library-index')||[],copy={...entry,id,name:entry.name+' 副本',at:Date.now()};await wfStore(null,[['library:'+id,data],['library-index',[copy,...index]]])});await refreshLibrary()})),wfButton('刪除',()=>libraryAction(async()=>{if(!confirm('刪除「'+entry.name+'」？此動作無法復原，請先下載需要保留的專案。'))return;clearTimeout(workflow.timer);await wfQueue(async()=>{const index=await wfStore('library-index')||[];await wfStore(null,[['library:'+entry.id,undefined],['library-index',index.filter(p=>p.id!==entry.id)]])});if(workflow.projectId===entry.id){workflow.internalInstall=true;try{installDocument({pages:[],active:0,autoNumber:true,publication:validatePublication(),numbering:'page'})}finally{workflow.internalInstall=false}workflow.projectId=null;workflow.projectName='';clearTimeout(draftTimer);draftDirty=false;const latest=await wfStore('latest');if(latest?.libraryId===entry.id)await wfStore(null,[['latest',undefined]])}await refreshLibrary()})));card.append(img,name,meta,actions);root.append(card)}if(!root.children.length)root.append(wfElement('p',q?'沒有符合的教材':'尚無教材。開啟截圖後會自動保存，也可按「保存目前教材」。'))}
$('libraryOpen').onclick=()=>libraryAction(async()=>{$('libraryDialog').showModal();if(image)await saveLibrary();await refreshLibrary()});
$('librarySearch').oninput=renderLibrary;
$('librarySave').onclick=()=>libraryAction(async()=>{if(await saveLibrary())await refreshLibrary()});
$('libraryNew').onclick=()=>libraryAction(async()=>{if(!await saveLibrary())return;workflow.internalInstall=true;try{installDocument({pages:[],active:0,autoNumber:true,publication:validatePublication(),numbering:'page'})}finally{workflow.internalInstall=false}workflow.projectId=null;workflow.projectName='';$('libraryDialog').close();$('file').click()});
projectData=function(){renumber();if(image&&!workflow.projectId)workflow.projectId=uid();const data=wfBase.projectData();data.workflow={numbering:workflow.numbering};draftIdentities.set(data,workflow.projectId);return data};
pageJSON=function(p){return {...wfBase.pageJSON(p),printBreaks:clone(p.printBreaks||[])}};
decodeProject=async function(data){const doc=await wfBase.decodeProject(data);const mode=data.workflow?.numbering;if(mode!==undefined&&!['page','document','manual'].includes(mode))throw Error('編號模式不正確');doc.numbering=mode||(doc.autoNumber?'page':'manual');const pages=data.version===1?[data]:data.pages;doc.pages.forEach((p,i)=>{const cuts=pages[i].printBreaks||[];if(!Array.isArray(cuts)||cuts.length>200||cuts.some(n=>!Number.isInteger(n)||n<=0||n>16000))throw Error('分頁位置格式不正確');p.printBreaks=[...new Set(cuts)].sort((a,b)=>a-b)});return doc};
installDocument=function(doc){clearTimeout(workflow.timer);if(!workflow.internalInstall){if(image)saveLibrary();workflow.projectId=null;workflow.projectName=''}workflow.numbering=doc.numbering||(doc.autoNumber?'page':'manual');wfBase.installDocument(doc)};
acceptImage=function(img,name){if(image)saveLibrary();const result=wfBase.acceptImage(img,name);if(result){workflow.projectId=null;workflow.projectName='';workflow.numbering='page';studio.autoNumber=true;scheduleDraft()}return result};
renumber=function(){if(!studio.autoNumber||workflow.numbering==='manual')return;capturePage();let next=1;for(const p of studio.pages){let n=workflow.numbering==='document'?next:1;for(const o of p.items)if(['step','number'].includes(o.type))o.n=Math.min(999,n++);p.nextNumber=Math.min(999,n);next=n}if(currentPage())$('nextNumber').value=currentPage().nextNumber};
$('numberScope').onchange=()=>{workflow.numbering=$('numberScope').value;studio.autoNumber=workflow.numbering!=='manual';commit()};
$('autoNumber').onchange=()=>{studio.autoNumber=$('autoNumber').checked;if(studio.autoNumber&&workflow.numbering==='manual')workflow.numbering='page';if(!studio.autoNumber)workflow.numbering='manual';commit()};
update=function(){renumber();wfBase.update();$('numberScope').value=studio.autoNumber?workflow.numbering:'manual';$('crossCopy').disabled=!studio.selection.size||studio.pages.length<2;for(const id of ['librarySave','templateSave','printPreview','downloadHTML'])$(id).disabled=!image};
$('crossCopy').onclick=()=>{const root=$('crossTargets');root.replaceChildren();studio.pages.forEach((p,i)=>{if(i===studio.active)return;const label=wfElement('label'),input=wfElement('input');label.className='choice';input.type='checkbox';input.value=p.id;label.append(input,document.createTextNode((i+1)+'. '+p.title));root.append(label)});$('crossStatus').textContent='將複製 '+studio.selection.size+' 個標註';$('crossDialog').showModal()};
$('crossAll').onclick=()=>{const boxes=[...$('crossTargets').querySelectorAll('input')],on=boxes.some(b=>!b.checked);boxes.forEach(b=>b.checked=on)};
function scaledCopies(originals,sx=1,sy=1){const ids=new Map(originals.map(o=>[o.id,uid()]));return originals.map(o=>{const n=clone(o);n.id=ids.get(o.id);n.x*=sx;n.y*=sy;n.w*=sx;n.h*=sy;n.size=Math.max(16,Math.min(160,n.size*Math.sqrt(sx*sy)));n.width=Math.max(2,Math.min(24,n.width*Math.sqrt(sx*sy)));if(n.type==='step')n.w=Math.max(160,Math.min(1600,n.w));if(n.type==='magnify'){n.sx*=sx;n.sy*=sy;n.sw*=sx;n.sh*=sy}if(n.linkTo){if(ids.has(n.linkTo)){n.linkTo=ids.get(n.linkTo);n.linkTip.x*=sx;n.linkTip.y*=sy}else{delete n.linkTo;delete n.linkTip}}return n})}
$('crossApply').onclick=()=>{try{capturePage();const ids=[...$('crossTargets').querySelectorAll('input:checked')].map(b=>b.value);if(!ids.length)throw Error('請勾選目標頁面');const source=[...studio.selection].map(i=>items[i]),plans=ids.map(id=>{const p=studio.pages.find(p=>p.id===id);if(!p)throw Error('頁面不存在');const w=(p.crop?.w||p.source.width)+p.margins.left+p.margins.right,h=(p.crop?.h||p.source.height)+p.margins.top+p.margins.bottom,copies=scaledCopies(source,$('crossScale').checked?w/image.width:1,$('crossScale').checked?h/image.height:1);if(p.items.length+copies.length>5000)throw Error('目標頁標註數量過多');base.validateProject({...pageJSON(p),items:[...p.items,...copies],version:1});return{p,copies}});plans.forEach(({p,copies})=>{p.items.push(...copies);p.history=p.history.slice(0,p.historyIndex+1);p.history.push(JSON.stringify({items:p.items,margins:p.margins,crop:p.crop}));if(p.history.length>80)p.history.shift();p.historyIndex=p.history.length-1});renumber();studio.revision++;update();render();scheduleDraft();$('crossDialog').close();toast('已複製到 '+plans.length+' 頁，各頁可獨立修改')}catch(e){$('crossStatus').textContent=e.message}};


// Save a reusable setup without screenshots or annotation content.
async function loadTemplates(){workflow.templates=await wfStore('teaching-templates')||[];renderTemplates()}
function renderTemplates(){const root=$('templateList');root.replaceChildren();for(const t of workflow.templates){const row=wfElement('div');row.className='template-row';row.append(wfElement('strong',t.name),wfButton('套用',async()=>{try{if(!image)throw Error('請先開啟新教材的圖片');const pub=validatePublication(t.publication),m=t.margins;paddedImage(croppedBase(sourceImage,studio.crop),m);let logo=null;if(pub.logo){logo=new Image();logo.src=pub.logo;await logo.decode()}if(!await saveHistory('套用範本前備份',true))throw Error('無法備份，請先下載專案');applyCanvasMargins({...m});plus.publication=pub;plus.logoImage=logo;for(const [id,value] of Object.entries(t.style))$(id).value=value;phrases=[...new Set([...t.phrases,...phrases])].slice(0,20);try{localStorage.setItem('studio-phrases',JSON.stringify(phrases))}catch{}renderPhrases();scheduleDraft();$('templatesDialog').close();toast('已套用文件與本頁留白；新標註會使用範本配色')}catch(e){$('templatesStatus').textContent=e.message}}),wfButton('刪除',async()=>{if(!confirm('刪除範本「'+t.name+'」？'))return;try{const next=workflow.templates.filter(x=>x.id!==t.id);await wfStore(null,[['teaching-templates',next]]);workflow.templates=next;renderTemplates()}catch(e){$('templatesStatus').textContent=e.message}}));root.append(row)}if(!root.children.length)root.append(wfElement('p','尚無範本，設定好封面、留白與配色後即可保存。'))}
$('templatesOpen').onclick=async()=>{$('templatesDialog').showModal();$('templatesStatus').textContent='';try{await loadTemplates()}catch(e){$('templatesStatus').textContent=e.message}};
$('templateSave').onclick=async()=>{if(!image)return;try{const name=$('templateName').value.trim();if(!name)throw Error('請輸入範本名稱');const old=await wfStore('teaching-templates')||[];if(old.length>=20)throw Error('最多 20 個範本，請先刪除不需要的範本');const t={id:uid(),name,publication:publicationJSON(),margins:{...margins},style:{color:$('color').value,size:$('size').value,width:$('width').value,stepWidth:$('stepWidth').value,textInput:$('textInput').value},phrases:clone(phrases)};await wfStore(null,[['teaching-templates',[t,...old]]]);$('templateName').value='';await loadTemplates();$('templatesStatus').textContent='範本已保存'}catch(e){$('templatesStatus').textContent=e.message}};
// Same replacement transformations as the confirmed action, but rendered on detached copies.
function replacementPreview(){const r=plus.replacing,p=currentPage();if(!r||!p)return;capturePage();$('compareBefore').src=pageCanvas(p).toDataURL();const mode=document.querySelector('[name=replaceMode]:checked').value,n={...p,source:r.img,items:mode==='clear'?[]:clone(p.items),crop:mode==='clear'?null:clone(p.crop),margins:mode==='clear'?zeroMargins():{...p.margins}};if(mode==='scale'){const sx=r.img.width/p.source.width,sy=r.img.height/p.source.height;n.items=scaledCopies(p.items,sx,sy);for(const o of n.items){o.x+=n.margins.left*(1-sx);o.y+=n.margins.top*(1-sy);if(o.type==='magnify'){o.sx+=n.margins.left*(1-sx);o.sy+=n.margins.top*(1-sy)}if(o.linkTip){o.linkTip.x+=n.margins.left*(1-sx);o.linkTip.y+=n.margins.top*(1-sy)}}if(n.crop){n.crop.x=Math.floor(n.crop.x*sx);n.crop.y=Math.floor(n.crop.y*sy);n.crop.w=Math.max(1,Math.min(r.img.width-n.crop.x,Math.round(p.crop.w*sx)));n.crop.h=Math.max(1,Math.min(r.img.height-n.crop.y,Math.round(p.crop.h*sy)))}}else if(mode==='position'&&n.crop&&(n.crop.x+n.crop.w>r.img.width||n.crop.y+n.crop.h>r.img.height)){for(const o of n.items){o.x+=n.crop.x;o.y+=n.crop.y;if(o.type==='magnify'){o.sx+=n.crop.x;o.sy+=n.crop.y}if(o.linkTip){o.linkTip.x+=n.crop.x;o.linkTip.y+=n.crop.y}}n.crop=null}try{$('compareAfter').src=pageCanvas(n).toDataURL()}catch(e){$('compareAfter').removeAttribute('src');$('replaceStatus').textContent=e.message}}
const previousReplaceInput=$('replaceFilePlus').onchange;
$('replaceFilePlus').onchange=async e=>{await previousReplaceInput(e);replacementPreview()};
document.querySelectorAll('[name=replaceMode]').forEach(e=>e.addEventListener('change',replacementPreview));
// A shared pagination plan powers both preview and the actual PDF.
function printDimensions(p){return{w:(p.crop?.w||p.source.width)+p.margins.left+p.margins.right,h:(p.crop?.h||p.source.height)+p.margins.top+p.margins.bottom}}
function printPlan(p){const {w,h}=printDimensions(p),max=Math.max(1,Math.floor(680*w/523)),manual=[...new Set(p.printBreaks||[])].filter(n=>n>0&&n<h).sort((a,b)=>a-b),ranges=[];let y=0;while(y<h){const forced=manual.find(n=>n>y),limit=Math.min(h,y+max,forced||Infinity);let end=limit,adjusted=true;if(end!==forced&&end<h){while(adjusted){adjusted=false;for(const o of p.items){if(!['step','text','number','magnify'].includes(o.type))continue;const b=bounds(o);if(b.y<end&&b.y+b.h>end&&b.y>y+1&&b.h<=max){end=Math.max(y+1,Math.floor(b.y-4));adjusted=true;break}}}}if(end<=y)end=limit;const crossing=p.items.some(o=>{if(!['step','text','number','magnify'].includes(o.type))return false;const b=bounds(o);return end<h&&b.y<end&&b.y+b.h>end});ranges.push({start:y,end,crossing});y=end}return ranges}
function makePrintJob(){capturePage();renumber();const pages=studio.pages.map(p=>({...p,items:clone(p.items),margins:{...p.margins},crop:clone(p.crop),printBreaks:clone(p.printBreaks||[])})),sheets=[];if(plus.publication.cover)sheets.push({cover:true});pages.forEach((p,i)=>printPlan(p).forEach(r=>sheets.push({page:i,...r})));return{pages,sheets,pub:publicationJSON(),logo:plus.logoImage}}
function renderPrintSheet(job,index,source){const s=job.sheets[index];if(s.cover)return coverCanvas(job.pub,job.logo,1190);const p=job.pages[s.page],body=source||pageCanvas(p),c=document.createElement('canvas');c.width=1190;c.height=1684;const g=c.getContext('2d'),ratio=1046/body.width,h=(s.end-s.start)*ratio;g.fillStyle='#fff';g.fillRect(0,0,c.width,c.height);if(job.pub.header||job.logo)g.drawImage(bandCanvas(job.pub.header,job.logo),72,28,1046,56);g.drawImage(titleCanvas((s.page+1)+'. '+p.title),72,90,1046,70);g.drawImage(body,0,s.start,body.width,s.end-s.start,72,192,1046,h);const offset=job.pub.cover?1:0;g.drawImage(bandCanvas((job.pub.footer?job.pub.footer+'　｜　':'')+(index+1-offset)+' / '+(job.sheets.length-offset)),72,1592,1046,56);return c}
function renderPrintPreview(){const job=workflow.printJob,s=job.sheets[workflow.printIndex],source=renderPrintSheet(job,workflow.printIndex),c=$('printCanvas');c.width=source.width;c.height=source.height;c.getContext('2d').drawImage(source,0,0);$('printCount').textContent=(workflow.printIndex+1)+' / '+job.sheets.length;$('printPrev').disabled=workflow.printIndex===0;$('printNext').disabled=workflow.printIndex===job.sheets.length-1;const cuts=job.sheets.filter(s=>s.crossing).length;$('printStatus').textContent=(s.cover?'封面':'原始第 '+(s.page+1)+' 頁，Y '+s.start+'–'+s.end+' px')+(cuts?'；'+cuts+' 個分頁仍切過標註，可調整位置或縮小標註。':'；目前分頁未切過說明標註。')}
function refreshPrintJob(){workflow.printJob=makePrintJob();workflow.printIndex=Math.min(workflow.printIndex,workflow.printJob.sheets.length-1);renderPrintPreview()}
$('printPreview').onclick=()=>{const select=$('printSource');select.replaceChildren();studio.pages.forEach((p,i)=>{const o=wfElement('option',(i+1)+'. '+p.title);o.value=i;select.append(o)});select.value=studio.active;$('printBreaks').value=(currentPage().printBreaks||[]).join(', ');workflow.printIndex=0;refreshPrintJob();$('printDialog').showModal()};
$('printSource').onchange=()=>{const i=Number($('printSource').value);$('printBreaks').value=(studio.pages[i].printBreaks||[]).join(', ');workflow.printIndex=workflow.printJob.sheets.findIndex(s=>s.page===i);renderPrintPreview()};
$('printApply').onclick=()=>{try{const p=studio.pages[Number($('printSource').value)],raw=$('printBreaks').value.trim(),values=raw?raw.split(/[,，\s]+/).map(Number):[],{h}=printDimensions(p);if(values.length>200||values.some(n=>!Number.isInteger(n)||n<=0||n>=h))throw Error('請輸入大於 0、小於圖片高度 '+h+' 的整數座標');p.printBreaks=[...new Set(values)].sort((a,b)=>a-b);studio.revision++;scheduleDraft();refreshPrintJob()}catch(e){$('printStatus').textContent=e.message}};
$('printReset').onclick=()=>{$('printBreaks').value='';$('printApply').click()};
$('printPrev').onclick=()=>{if(workflow.printIndex>0){workflow.printIndex--;renderPrintPreview()}};
$('printNext').onclick=()=>{if(workflow.printIndex+1<workflow.printJob.sheets.length){workflow.printIndex++;renderPrintPreview()}};
buildPDF=async function(){const job=makePrintJob();await loadScript('vendor/pdf-lib.min.js');const pdf=await PDFLib.PDFDocument.create();let source=null,last=-1;for(let i=0;i<job.sheets.length;i++){const s=job.sheets[i];if(!s.cover&&s.page!==last){if(source)source.width=source.height=1;source=pageCanvas(job.pages[s.page]);last=s.page}const c=renderPrintSheet(job,i,source),png=await pdf.embedPng(await(await canvasBlob(c)).arrayBuffer());pdf.addPage([595.28,841.89]).drawImage(png,{x:0,y:0,width:595.28,height:841.89});c.width=c.height=1;$('bookStatus').textContent='正在匯出 '+(i+1)+' / '+job.sheets.length+' 張…';await new Promise(r=>setTimeout(r,0))}if(source)source.width=source.height=1;return pdf.save()};
