function shareHTML(){capturePage();renumber();const pub=publicationJSON(),pages=[],steps=[];if(pub.cover){pages.push({title:pub.title||'操作教學',image:coverCanvas(pub,plus.logoImage,1000).toDataURL()});steps.push({page:0,caption:[pub.unit,pub.date,pub.version].filter(Boolean).join(' · ')})}studio.pages.forEach((p,i)=>{const pi=pages.length,c=publicationPage(p,i,studio.pages.length,pub,plus.logoImage);pages.push({title:p.title,image:c.toDataURL()});const numbered=p.items.filter(o=>['step','number'].includes(o.type)).sort((a,b)=>a.n-b.n);if(numbered.length)numbered.forEach(o=>steps.push({page:pi,caption:'步驟 '+o.n+(p.items.some(m=>{if(m.type!=='mask')return false;const a=bounds(o),b=bounds(m);return a.x<b.x+b.w&&a.x+a.w>b.x&&a.y<b.y+b.h&&a.y+a.h>b.y})?'：說明已遮蔽':o.text?'：'+o.text:'')}));else steps.push({page:pi,caption:'閱讀本頁教學'})});const payload=JSON.stringify({title:pub.title||'操作教學',pages,steps}).replace(/</g,'\\u003c').replace(/\u2028/g,'\\u2028').replace(/\u2029/g,'\\u2029');const script="const data=JSON.parse(document.getElementById('data').textContent);let current=0;const el=id=>document.getElementById(id);function show(){const s=data.steps[current],p=data.pages[s.page];el('title').textContent=p.title;el('picture').src=p.image;el('caption').textContent=s.caption;el('progress').textContent=(current+1)+' / '+data.steps.length;el('previous').disabled=current===0;el('next').disabled=current===data.steps.length-1}el('previous').onclick=()=>{if(current>0){current--;show()}};el('next').onclick=()=>{if(current<data.steps.length-1){current++;show()}};document.addEventListener('keydown',e=>{if(e.key==='ArrowLeft')el('previous').click();if(e.key==='ArrowRight')el('next').click()});document.title=data.title;show();";return '<!doctype html><html lang="zh-Hant"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src \'none\'; img-src data:; style-src \'unsafe-inline\'; script-src \'unsafe-inline\'; connect-src \'none\'; base-uri \'none\'; form-action \'none\'"><title>操作教學</title><style>body{font:18px/1.6 system-ui,sans-serif;margin:0;background:#eef2f8;color:#18304b}main{max-width:1100px;margin:auto;padding:20px}img{max-width:100%;display:block;margin:auto}figure{margin:0;background:white;overflow:auto}nav{display:flex;justify-content:space-between;align-items:center;gap:16px;padding:16px 0;position:sticky;bottom:0;background:#eef2f8}button{font:inherit;padding:10px 24px;border:1px solid #ccd5e0;border-radius:8px;background:white}button:disabled{opacity:.4}#caption{white-space:pre-wrap;overflow-wrap:anywhere;padding:18px;background:white;border-left:4px solid #2563eb}h1{overflow-wrap:anywhere}small{color:#526580}</style><main><h1 id="title"></h1><figure><img id="picture" alt="教學截圖"></figure><p id="caption"></p><nav><button id="previous">上一步</button><span id="progress" role="status"></span><button id="next">下一步</button></nav><small>離線互動教學 · 可使用左右方向鍵</small></main><script type="application/json" id="data">'+payload+'</script><script>'+script+'</script></html>'}
$('downloadHTML').onclick=()=>{const action=()=>{try{const html=shareHTML();if(html.length>120*1024*1024)throw Error('分享檔過大，請減少頁數');downloadBlob(new Blob([html],{type:'text/html;charset=utf-8'}),'互動教學.html');$('bookStatus').textContent='互動教學已下載；可離線開啟或寄送 HTML 檔。只包含合成圖片與步驟說明。'}catch(e){$('bookStatus').textContent=e.message}};const issues=inspectExport(true,false);if(issues.length)showChecks(issues,action);else action()};


