$('snapEnabled').onchange=()=>{workflow.snap=$('snapEnabled').checked;workflow.guides=[];render()};
function snapSelection(event){if(!workflow.snap||event.altKey||drag?.kind!=='move')return;const moving=[...studio.selection].filter(i=>items[i]&&!items[i].locked&&!items[i].linkTo);if(!moving.length)return;const boxes=moving.map(i=>bounds(items[i])),left=Math.min(...boxes.map(b=>b.x)),right=Math.max(...boxes.map(b=>b.x+b.w)),top=Math.min(...boxes.map(b=>b.y)),bottom=Math.max(...boxes.map(b=>b.y+b.h)),xs=[0,image.width/2,image.width],ys=[0,image.height/2,image.height];items.forEach((o,i)=>{if(studio.selection.has(i))return;const b=bounds(o);xs.push(b.x,b.x+b.w/2,b.x+b.w);ys.push(b.y,b.y+b.h/2,b.y+b.h)});const closest=(own,targets)=>{let best=null;for(const a of own)for(const b of targets)if(Math.abs(a-b)<=7/zoom&&(!best||Math.abs(a-b)<Math.abs(best.delta)))best={delta:b-a,line:b};return best},x=closest([left,(left+right)/2,right],xs),y=closest([top,(top+bottom)/2,bottom],ys);workflow.guides=[];if(x)workflow.guides.push({axis:'x',value:x.line});if(y)workflow.guides.push({axis:'y',value:y.line});moving.forEach(i=>{items[i].x+=x?.delta||0;items[i].y+=y?.delta||0})}
canvas.addEventListener('pointermove',e=>{workflow.guides=[];if(drag?.kind==='move'){snapSelection(e);render()}});
for(const name of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(name,()=>{workflow.guides=[];render()});
render=function(){wfBase.render();if(!image)return;ctx.save();ctx.strokeStyle='#0ea5e9';ctx.lineWidth=1/zoom;ctx.setLineDash([6/zoom,4/zoom]);for(const g of workflow.guides){ctx.beginPath();if(g.axis==='x'){ctx.moveTo(g.value,0);ctx.lineTo(g.value,image.height)}else{ctx.moveTo(0,g.value);ctx.lineTo(image.width,g.value)}ctx.stroke()}ctx.restore();if((matchMedia('(pointer:coarse)').matches||touchPoints.size)&&studio.selection.size===1&&selected>=0&&!items[selected]?.locked){const b=bounds(items[selected]),r=10/zoom;ctx.save();ctx.fillStyle='#fff';ctx.strokeStyle='#2563eb';ctx.lineWidth=2/zoom;ctx.beginPath();ctx.arc(b.x+b.w,b.y+b.h,r,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.restore()}};
// Capture multi-touch before the existing single-pointer drawing handlers.
const touchPoints=new Map();let touchStart=null,gesture=null,touchSuppress=false,panDrag=null;
$('fit').insertAdjacentHTML('beforebegin','<button id="panCanvas" aria-pressed="false" title="切換拖曳平移畫布">平移</button>');
$('panCanvas').onclick=()=>{workflow.pan=!workflow.pan;$('panCanvas').setAttribute('aria-pressed',String(workflow.pan));canvas.style.cursor=workflow.pan?'grab':'';toast(workflow.pan?'拖曳可平移畫布，再按一次返回標註':'已返回標註操作')};
function stopPointer(e){e.preventDefault();e.stopImmediatePropagation()}
function midpoint(){const [a,b]=[...touchPoints.values()];return{x:(a.x+b.x)/2,y:(a.y+b.y)/2,d:Math.max(1,Math.hypot(a.x-b.x,a.y-b.y))}}
canvas.addEventListener('pointerdown',e=>{if(!image)return;if(e.pointerType==='touch'){if(!touchPoints.size){touchStart={state:snapshot(),history:clone(history),index:historyIndex};touchSuppress=false}touchPoints.set(e.pointerId,{x:e.clientX,y:e.clientY});if(touchPoints.size>=2){stopPointer(e);canvas.setPointerCapture(e.pointerId);if(!gesture){if(touchStart&&!workflow.pan){drag=null;cropPreview=null;restore(touchStart.state);history=touchStart.history;historyIndex=touchStart.index;capturePage()}const mid=midpoint(),r=canvas.getBoundingClientRect();gesture={distance:mid.d,zoom,x:(mid.x-r.left)/zoom,y:(mid.y-r.top)/zoom};touchSuppress=true;panDrag=null}return}}if(workflow.pan){stopPointer(e);canvas.setPointerCapture(e.pointerId);panDrag={id:e.pointerId,x:e.clientX,y:e.clientY,left:$('board').scrollLeft,top:$('board').scrollTop};}},true);
canvas.addEventListener('pointermove',e=>{if(touchPoints.has(e.pointerId))touchPoints.set(e.pointerId,{x:e.clientX,y:e.clientY});if(gesture||touchSuppress){stopPointer(e);if(gesture&&touchPoints.size>=2){const mid=midpoint();setZoom(gesture.zoom*mid.d/gesture.distance);const r=canvas.getBoundingClientRect();$('board').scrollLeft+=r.left+gesture.x*zoom-mid.x;$('board').scrollTop+=r.top+gesture.y*zoom-mid.y}return}if(panDrag?.id===e.pointerId){stopPointer(e);$('board').scrollLeft=panDrag.left+panDrag.x-e.clientX;$('board').scrollTop=panDrag.top+panDrag.y-e.clientY}},true);
function finishTouch(e){const wasGesture=gesture||touchSuppress;touchPoints.delete(e.pointerId);if(wasGesture){stopPointer(e);gesture=null;if(!touchPoints.size){touchSuppress=false;touchStart=null}render()}else if(panDrag?.id===e.pointerId){stopPointer(e);panDrag=null}else if(!touchPoints.size)touchStart=null}
canvas.addEventListener('pointerup',finishTouch,true);
canvas.addEventListener('pointercancel',finishTouch,true);
